<script>
// Render cart items
function renderCart(){
  const cart = JSON.parse(localStorage.getItem('cartItems')||'[]');
  const container = document.getElementById('cart-items');
  let total = 0;
  if(cart.length===0){
    container.innerHTML='<p>购物车为空</p>';
  }else{
    cart.forEach(item=>{
      const div = document.createElement('div');
      div.className='order-item';
      div.innerHTML='<span>'+item.name+'</span><span>'+item.price+'元</span>';
      container.appendChild(div);
      total+=item.price;
    });
  }
  document.getElementById('total-price').textContent='总价：'+total+'元';
}
renderCart();
</script>
